#!/usr/bin/env python3
"""
Ambient Context Retrieval Demo - Offline & Deterministic

Reads conversations, extracts entities, builds relationships,
and outputs summary, context packet, and entities CSV.
"""

import json
import csv
import re
from pathlib import Path
from datetime import datetime
from collections import defaultdict

# Configuration
DATA_FILE = Path('data/conversations.json')
SUMMARY_FILE = Path('summary.txt')
CONTEXT_PACKET_FILE = Path('context_packet.json')
ENTITIES_CSV_FILE = Path('entities.csv')

# Entity patterns for extraction
PEOPLE_PATTERNS = [
    r'\b(Avery|Jordan|Mina|Alex|Taylor|Casey|Riley)\b',
]

PROJECT_PATTERNS = [
    r'Project\s+([A-Z][a-zA-Z]+)',
    r'(ambient\s+dashboard)',
    r'(search\s+index)',
    r'(privacy\s+review)',
]

ORGANIZATION_PATTERNS = [
    r'([A-Z][a-z]+\s+[A-Z][a-z]+\s+Labs)',
    r'([A-Z][a-z]+\s+Inc\.)',
    r'([A-Z][a-z]+\s+Corp)',
]

DATE_PATTERNS = [
    r'(\d{4}-\d{2}-\d{2})',
    r'(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)',
    r'(next\s+week|this\s+week|tomorrow)',
]

def load_conversations(filepath):
    """Load conversations from JSON file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def extract_entities(text):
    """Extract entities from text using pattern matching."""
    entities = {'people': [], 'projects': [], 'organizations': [], 'dates': []}

    # Extract people
    for pattern in PEOPLE_PATTERNS:
        matches = re.findall(pattern, text, re.IGNORECASE)
        entities['people'].extend([m if isinstance(m, str) else m[0] for m in matches])

    # Extract projects
    for pattern in PROJECT_PATTERNS:
        matches = re.findall(pattern, text, re.IGNORECASE)
        for m in matches:
            if isinstance(m, tuple):
                entities['projects'].extend([x for x in m if x])
            else:
                entities['projects'].append(m)

    # Extract organizations
    for pattern in ORGANIZATION_PATTERNS:
        matches = re.findall(pattern, text)
        for m in matches:
            if isinstance(m, tuple):
                entities['organizations'].extend([x for x in m if x])
            else:
                entities['organizations'].append(m)

    # Extract dates
    for pattern in DATE_PATTERNS:
        matches = re.findall(pattern, text, re.IGNORECASE)
        for m in matches:
            if isinstance(m, tuple):
                entities['dates'].extend([x for x in m if x])
            else:
                entities['dates'].append(m)

    return entities

def build_relationships(conversations, all_entities):
    """Build relationships between entities based on conversation context."""
    relationships = []

    for conv in conversations:
        text = conv['text'].lower()
        speaker = conv['speaker']

        # Check for "works_on" or project association
        for project in all_entities['projects']:
            project_lower = project.lower()
            if project_lower in text:
                # Check if speaker is associated with project
                if speaker.lower() in text.lower():
                    relationships.append({
                        'source': speaker,
                        'target': project,
                        'relation': 'works_on',
                        'evidence': conv['text'][:80]
                    })

        # Check for "client_of" relationship (project -> organization)
        for project in all_entities['projects']:
            for org in all_entities['organizations']:
                if project.lower() in text and org.lower() in text:
                    relationships.append({
                        'source': project,
                        'target': org,
                        'relation': 'client_of',
                        'evidence': conv['text'][:80]
                    })

        # Check for "mentioned_with" between people
        for person in all_entities['people']:
            if person.lower() in text and speaker != person:
                relationships.append({
                    'source': speaker,
                    'target': person,
                    'relation': 'mentioned_with',
                    'evidence': conv['text'][:80]
                })

        # Check for "depends_on" relationships
        if 'depends on' in text or 'depends on' in text.lower():
            # Find what depends on what
            for project in all_entities['projects']:
                if project.lower() in text:
                    for dep in all_entities['projects']:
                        if dep != project and dep.lower() in text:
                            relationships.append({
                                'source': project,
                                'target': dep,
                                'relation': 'depends_on',
                                'evidence': conv['text'][:80]
                            })

        # Check for deadline relationships
        for date in all_entities['dates']:
            if date.lower() in text:
                for project in all_entities['projects']:
                    if project.lower() in text:
                        relationships.append({
                            'source': project,
                            'target': date,
                            'relation': 'has_deadline',
                            'evidence': conv['text'][:80]
                        })

    # Deduplicate relationships
    seen = set()
    unique_relationships = []
    for rel in relationships:
        key = (rel['source'], rel['target'], rel['relation'])
        if key not in seen:
            seen.add(key)
            unique_relationships.append(rel)

    return unique_relationships

def generate_summary(conversations, all_entities, relationships):
    """Generate a human-readable summary."""
    lines = []
    lines.append("=" * 60)
    lines.append("AMBIENT CONTEXT RETRIEVAL - SUMMARY")
    lines.append("=" * 60)
    lines.append("")

    # Conversation overview
    lines.append("CONVERSATION OVERVIEW")
    lines.append("-" * 40)
    lines.append(f"Total conversations: {len(conversations)}")
    if conversations:
        dates = set(c['timestamp'][:10] for c in conversations)
        lines.append(f"Date range: {', '.join(sorted(dates))}")
    lines.append("")

    # Extracted entities
    lines.append("EXTRACTED ENTITIES")
    lines.append("-" * 40)

    lines.append(f"\nPeople ({len(all_entities['people'])}):")
    for person in sorted(set(all_entities['people'])):
        lines.append(f"  - {person}")

    lines.append(f"\nProjects ({len(all_entities['projects'])}):")
    for project in sorted(set(all_entities['projects'])):
        lines.append(f"  - {project}")

    lines.append(f"\nOrganizations ({len(all_entities['organizations'])}):")
    for org in sorted(set(all_entities['organizations'])):
        lines.append(f"  - {org}")

    lines.append(f"\nDates ({len(all_entities['dates'])}):")
    for date in sorted(set(all_entities['dates'])):
        lines.append(f"  - {date}")

    lines.append("")

    # Relationships
    lines.append("RELATIONSHIPS")
    lines.append("-" * 40)
    for rel in relationships:
        lines.append(f"  {rel['source']} --[{rel['relation']}]--> {rel['target']}")

    lines.append("")
    lines.append("=" * 60)
    lines.append(f"Generated: {datetime.now().isoformat()}")
    lines.append("=" * 60)

    return "\n".join(lines)

def generate_context_packet(conversations, all_entities, relationships):
    """Generate the machine-readable context packet."""
    # Build resolved entities with unique IDs
    resolved_entities = []
    entity_id = 0
    seen_entities = set()

    for entity_type in ['people', 'projects', 'organizations', 'dates']:
        for entity in all_entities[entity_type]:
            if entity not in seen_entities:
                seen_entities.add(entity)
                resolved_entities.append({
                    'id': f'e{entity_id:03d}',
                    'name': entity,
                    'type': entity_type.rstrip('s') if entity_type != 'people' else 'person',
                    'mentions': all_entities[entity_type].count(entity)
                })
                entity_id += 1

    context_packet = {
        'metadata': {
            'version': '1.0',
            'generated_at': datetime.now().isoformat(),
            'source': 'ambient_context_demo'
        },
        'recent_conversations': conversations,
        'resolved_entities': resolved_entities,
        'relationships': relationships,
        'summary_stats': {
            'total_conversations': len(conversations),
            'total_entities': len(resolved_entities),
            'total_relationships': len(relationships),
            'entity_counts': {
                'people': len(set(all_entities['people'])),
                'projects': len(set(all_entities['projects'])),
                'organizations': len(set(all_entities['organizations'])),
                'dates': len(set(all_entities['dates']))
            }
        }
    }

    return context_packet

def generate_entities_csv(all_entities):
    """Generate CSV data for entities."""
    rows = []

    for person in set(all_entities['people']):
        rows.append({'name': person, 'type': 'person'})

    for project in set(all_entities['projects']):
        rows.append({'name': project, 'type': 'project'})

    for org in set(all_entities['organizations']):
        rows.append({'name': org, 'type': 'organization'})

    for date in set(all_entities['dates']):
        rows.append({'name': date, 'type': 'date'})

    return rows

def main():
    print("Ambient Context Retrieval Demo")
    print("=" * 40)

    # Load conversations
    print(f"\nLoading conversations from {DATA_FILE}...")
    conversations = load_conversations(DATA_FILE)
    print(f"  Loaded {len(conversations)} conversations")

    # Extract all entities
    print("\nExtracting entities...")
    all_entities = {'people': [], 'projects': [], 'organizations': [], 'dates': []}

    for conv in conversations:
        entities = extract_entities(conv['text'])
        for entity_type in all_entities:
            all_entities[entity_type].extend(entities[entity_type])

    print(f"  People: {len(set(all_entities['people']))}")
    print(f"  Projects: {len(set(all_entities['projects']))}")
    print(f"  Organizations: {len(set(all_entities['organizations']))}")
    print(f"  Dates: {len(set(all_entities['dates']))}")

    # Build relationships
    print("\nBuilding relationships...")
    relationships = build_relationships(conversations, all_entities)
    print(f"  Found {len(relationships)} relationships")

    # Generate summary
    print(f"\nGenerating summary ({SUMMARY_FILE})...")
    summary = generate_summary(conversations, all_entities, relationships)
    SUMMARY_FILE.write_text(summary, encoding='utf-8')

    # Generate context packet
    print(f"Generating context packet ({CONTEXT_PACKET_FILE})...")
    context_packet = generate_context_packet(conversations, all_entities, relationships)
    CONTEXT_PACKET_FILE.write_text(
        json.dumps(context_packet, indent=2),
        encoding='utf-8'
    )

    # Generate entities CSV
    print(f"Generating entities CSV ({ENTITIES_CSV_FILE})...")
    csv_rows = generate_entities_csv(all_entities)
    with open(ENTITIES_CSV_FILE, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['name', 'type'])
        writer.writeheader()
        writer.writerows(csv_rows)

    print("\n" + "=" * 40)
    print("Output files generated:")
    print(f"  - {SUMMARY_FILE}")
    print(f"  - {CONTEXT_PACKET_FILE}")
    print(f"  - {ENTITIES_CSV_FILE}")
    print("\nDone!")

if __name__ == '__main__':
    main()
